mapper.select:
SELECT 
FROM user_policy_consents c
JOIN policy_versions v ON v.id = c.policy_version_id
WHERE c.user_id = #{userId} AND v.policy_type = #{policyType}
  AND c.created_at <= #{asOf}
ORDER BY c.id DESC LIMIT 1

SELECT 
FROM user_policy_consents c
JOIN policy_versions v ON v.id = c.policy_version_id
WHERE c.user_id = #{userId} AND v.policy_type = #{policyType}
  AND COALESCE(v.consent_basis_version_id, v.id) = #{basisId}
  AND c.created_at <= #{asOf}
ORDER BY c.id DESC LIMIT 1

